local function C_1a()
	local script = LMG2L["LocalScript_1a"];
	-- Buton referansı (Scriptin bir butonun içinde olduğunu varsayıyorum)

	local button = script.Parent



	-- Mevcut değişkenlerin

	local player = game.Players.LocalPlayer

	local char = player.Character or player.CharacterAdded:Wait()

	local tool



	-- SyncAPI Bulma Mantığı

	for i,v in player:GetDescendants() do

	    if v.Name == "SyncAPI" then

	        tool = v.Parent

	    end

	end

	if not tool then

	    for i,v in game.ReplicatedStorage:GetDescendants() do

	        if v.Name == "SyncAPI" then

	            tool = v.Parent

	        end

	    end

	end



	-- Remote kontrolü

	local remote = tool:WaitForChild("SyncAPI"):WaitForChild("ServerEndpoint")



	-- ANA FONKSİYONLARIN (DEĞİŞTİRİLMEDİ)

	function _(args)

	    remote:InvokeServer(unpack(args))

	end



	function CreatePart(cf,parent)

	    local args = {[1] = "CreatePart",[2] = "Normal",[3] = cf,[4] = parent}

	    _(args)

	end



	function SetAnchor(boolean,part)

	    local args = {[1] = "SyncAnchor",[2] = {[1] = {["Part"] = part,["Anchored"] = boolean}}}

	    _(args)

	end



	function SetMesh(part,meshid)

	    local args = {[1] = "SyncMesh",[2] = {[1] = {["Part"] = part,["MeshId"] = "rbxassetid://"..meshid}}}

	    _(args)

	end



	function SetTexture(part, texid)

	    local args = {[1] = "SyncMesh",[2] = {[1] = {["Part"] = part,["TextureId"] = "rbxassetid://"..texid}}}

	    _(args)

	end



	function SetName(part, stringg)

	    local args = {[1] = "SetName",[2] = {[1] = part},[3] = stringg}

	    _(args)

	end



	function MeshResize(part,size)

	    local args = {[1] = "SyncMesh",[2] = {[1] = {["Part"] = part,["Scale"] = size}}}

	    _(args)

	end



	function AddMesh(part)

	    local args = {[1] = "CreateMeshes",[2] = {[1] = {["Part"] = part}}}

	    _(args)

	end



	function SetLocked(part,boolean)

	    local args = {[1] = "SetLocked",[2] = {[1] = part},[3] = boolean}

	    _(args)

	end



	-- GÖKYÜZÜ OLUŞTURMA FONKSİYONU

	function Sky(id)

	    local root = char:WaitForChild("HumanoidRootPart")

	    local pos = root.CFrame + Vector3.new(0, 6, 0)

	    CreatePart(pos, workspace)

	    task.wait(0.3) -- Sunucunun parçayı algılaması için hafif bir bekleme



	    local skyPart

	    for _, v in workspace:GetChildren() do

	        if v:IsA("BasePart") and (v.Position - pos.Position).magnitude < 1 then

	            skyPart = v

	            break

	        end

	    end



	    if skyPart then

	        SetName(skyPart, "Sky")

	        AddMesh(skyPart)

	        SetMesh(skyPart, "111891702759441")

	        SetTexture(skyPart, id)

	        MeshResize(skyPart, Vector3.new(1000, 1000, 1000))

	        SetLocked(skyPart, true)

	        SetAnchor(true, skyPart)

	    end

	end



	--- BUTON TIKLAMA OLAYI ---

	button.MouseButton1Click:Connect(function()

	    print("Gökyüzü oluşturuluyor...")

	    Sky("92149450424187") -- Buradaki ID'yi değiştirebilirsin

	end)	
end;
task.spawn(C_1a);
