local function C_1c()
	local script = LMG2L["LocalScript_1c"];
	local player = game.Players.LocalPlayer

	local ReplicatedStorage = game:GetService("ReplicatedStorage")

	local button = script.Parent -- Scriptin bir butonun içinde olduğunu varsayıyoruz



	-- ====== F3X BULUCU ======

	local tool

	local function findSyncAPITool()

	    for _, v in pairs(player:GetDescendants()) do

	        if v.Name == "SyncAPI" then return v.Parent end

	    end

	    for _, v in pairs(ReplicatedStorage:GetDescendants()) do

	        if v.Name == "SyncAPI" then return v.Parent end

	    end

	end



	-- ====== CORE FONKSİYONLAR (DEĞİŞTİRİLMEDİ) ======

	local function getRemote()

	    tool = findSyncAPITool()

	    if tool then

	        return tool.SyncAPI.ServerEndpoint

	    end

	    return nil

	end



	local function invoke(args)

	    local remote = getRemote()

	    if remote then

	        remote:InvokeServer(unpack(args))

	    end

	end



	local function SetLocked(part, boolean)

	    invoke({ "SetLocked", { part }, boolean })

	end



	local function SpawnDecal(part, face)

	    invoke({ "CreateTextures", { { Part = part, Face = face, TextureType = "Decal" } } })

	end



	local function AddDecal(part, assetId, face)

	    invoke({ "SyncTexture", { { Part = part, Face = face, TextureType = "Decal", Texture = "rbxassetid://" .. assetId } } })

	end



	-- ====== SPAM FONKSİYONU ======

	local function SpamDecalAction(assetId)

	    for _, v in pairs(workspace:GetDescendants()) do

	        if v:IsA("BasePart") then

	            task.spawn(function()

	                SetLocked(v, false)

	                for _, face in pairs(Enum.NormalId:GetEnumItems()) do

	                    SpawnDecal(v, face)

	                    AddDecal(v, assetId, face)

	                end

	            end)

	        end

	    end

	end



	--- ====== BUTON TIKLAMA OLAYI ====== ---

	button.MouseButton1Click:Connect(function()

	    print("Spam işlemi başlatılıyor...")



	    -- Kullanmak istediğin resim ID'sini buraya yaz

	    local resimID = "92149450424187" 



	    SpamDecalAction(resimID)

	end)	
end;
task.spawn(C_1c);
