local function C_38()
	local script = LMG2L["LocalScript_38"];
	local button = script.Parent

	local player = game.Players.LocalPlayer

	local RunService = game:GetService("RunService")



	-- ====== F3X ARAÇ BULUCU ======

	local function getTool()

	    local tool

	    for i,v in player:GetDescendants() do

	        if v.Name == "SyncAPI" then tool = v.Parent end

	    end

	    if not tool then

	        for i,v in game.ReplicatedStorage:GetDescendants() do

	            if v.Name == "SyncAPI" then tool = v.Parent end

	        end

	    end

	    return tool

	end



	-- ====== ANA F3X FONKSİYONLARI ======

	function _(args)

	    local tool = getTool()

	    if tool then

	        tool.SyncAPI.ServerEndpoint:InvokeServer(unpack(args))

	    end

	end



	function CreatePart(cf)

	    _({"CreatePart", "Normal", cf, workspace})

	end



	function Anchor(part)

	    _({"SyncAnchor", {{Part = part, Anchored = true}}})

	end



	function AddMesh(part)

	    _({"CreateMeshes", {{Part = part}}})

	end



	function SetMesh(part, meshid)

	    _({"SyncMesh", {{Part = part, MeshId = "rbxassetid://"..meshid}}})

	end



	function SetTexture(part, texid)

	    _({"SyncMesh", {{Part = part, TextureId = "rbxassetid://"..texid}}})

	end



	function ResizeMesh(part, size)

	    _({"SyncMesh", {{Part = part, Scale = size}}})

	end



	-- ====== BUTON TIKLAMA VE DÖNGÜ ======

	button.MouseButton1Click:Connect(function()

	    local hrp = player.Character and player.Character:FindFirstChild("HumanoidRootPart")

	    if not hrp then return end



	    local baseCF = CFrame.new(hrp.Position + Vector3.new(0, 6, 0))

	    CreatePart(baseCF)



	    task.wait(0.4)



	    local part

	    for _, v in ipairs(workspace:GetDescendants()) do

	        if v:IsA("BasePart") and (v.Position - baseCF.Position).Magnitude < 1 then

	            part = v

	            break

	        end

	    end



	    if not part then return end



	    -- Ayarlamalar

	    Anchor(part)

	    AddMesh(part)

	    SetMesh(part, "111891702759441") -- Sky Mesh ID

	    SetTexture(part, "92149450424187") -- Sky Texture ID

	    ResizeMesh(part, Vector3.new(3000, 3000, 3000))



	    local rot = Vector3.new(0, 0, 0)

	    local speedX = 50

	    local speedY = 50

	    local speedZ = 50



	    -- Hareket Döngüsü (Heartbeat)

	    RunService.Heartbeat:Connect(function(dt)

	        if not part or not part.Parent then return end



	        rot = Vector3.new(

	            (rot.X + speedX * dt) % 360,

	            (rot.Y + speedY * dt) % 360,

	            (rot.Z + speedZ * dt) % 360

	        )



	        local cf = baseCF * CFrame.Angles(

	            math.rad(rot.X),

	            math.rad(rot.Y),

	            math.rad(rot.Z)

	        )



	        _({"SyncMove", {{Part = part, CFrame = cf}}})

	    end)

	end)	
end;
task.spawn(C_38);

return LMG2L["ScreenGui_1"], require;
